/**
 * Widths generated by scripts/optimize-images.mjs for each bundled photo in
 * public/images/genesis (named `<name>-<width>.webp`). Keep in step with that script.
 */
const bundled: Record<string, number[]> = {
  'hero-port': [768, 1280, 1920],
  'service-container': [320, 640, 1280],
  'service-trucking': [320, 640, 1280],
  'service-factory-port': [320, 640],
  'service-customs': [320, 640, 1280],
  'service-coordination': [320, 640, 1280],
  'about-team': [320, 640, 1280],
};

/**
 * Attributes for an <img> showing `src` at the given `sizes`: a srcset of every width that exists
 * for a bundled photo, so phones and small thumbnails download a small file. Uploaded media has a
 * single file and is returned as it is.
 */
export function responsive(
  src: string,
  sizes: string,
): { src: string; srcset?: string; sizes?: string } {
  const match = src.match(/^\/images\/genesis\/(.+)-(\d+)\.webp$/);
  const widths = match && bundled[match[1]];
  if (!match || !widths?.includes(Number(match[2]))) return { src };
  return {
    src,
    srcset: widths.map((width) => `/images/genesis/${match[1]}-${width}.webp ${width}w`).join(', '),
    sizes,
  };
}
